// AudioDriver: plays the baked voice clips (assets/audio/*.m4a, voice
// "Evan (Enhanced)", generated by tools/bake-audio.py) and drives karaoke +
// gating through per-word timers from js/audio-manifest.js. This replaced the
// live speechSynthesis stub on 2026-08-15: browser voices were robotic,
// varied per participant device, and a gesture-less utterance could wedge
// Chrome's speech engine browser-wide. Baked files play the same calm voice
// everywhere. Rerun the bake after any script change.
//
// Same API as always: unlock(), speak(text, {onWord, onEnd}) -> {durationMs},
// stop(fade), durationMs(text). Screens never touch playback directly.
import { MANIFEST } from './audio-manifest.js';

const params = new URLSearchParams(location.search);
export const CFG = {
  // ?fast compresses audio + timers for dev/review walkthroughs (no sound)
  wordMs: params.has('fast') ? 70 : 360,   // synthetic pace when no clip plays
  tailMs: 500,                              // synthetic-mode pause after last word
  endPadMs: 120,                            // real-clip pause after file ends before onEnd
  toastMs: params.has('fast') ? 3500 : 15000, // inactivity threshold for toast + pulse (Justin: 15s)
  useVoice: !params.has('mute') && !params.has('fast'), // ?mute disables sound
};

// Preload every clip at boot: files are small and local, so pre-warmed
// elements start near-instantly and the word timers stay in sync.
const players = new Map();
if (CFG.useVoice) {
  for (const entry of Object.values(MANIFEST)) {
    if (!players.has(entry.src)) {
      const a = new window.Audio(entry.src);
      a.preload = 'auto';
      players.set(entry.src, a);
    }
  }
}

let currentRun = null;
let fadeSeq = 0; // invalidates in-flight fades when the element is reused

function resetPlayer(player) {
  fadeSeq += 1;
  player.pause();
  player.currentTime = 0;
  player.volume = 1;
}

function stopPlayback(player, fade) {
  if (!player) return;
  if (!fade || player.paused) { resetPlayer(player); return; }
  // Justin: early advance FADES audio out, never hard-cuts.
  fadeSeq += 1;
  const token = fadeSeq;
  const step = () => {
    if (token !== fadeSeq) return; // element was reclaimed by a new run
    if (player.volume > 0.08) {
      player.volume = Math.max(0, player.volume - 0.08);
      setTimeout(step, 30);
    } else {
      player.pause(); player.currentTime = 0; player.volume = 1;
    }
  };
  step();
}

function cancelRun(fade) {
  if (!currentRun) return;
  currentRun.timers.forEach(clearTimeout);
  stopPlayback(currentRun.player, fade);
  currentRun = null;
}

export const Audio = {
  unlocked: false,

  // Must be called from a user gesture (P0 Begin tap / dev scrim) — iOS Safari
  // only plays media elements that a gesture has primed. Prime every clip.
  unlock() {
    if (this.unlocked) return;
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (Ctx) { const ctx = new Ctx(); ctx.resume(); }
      for (const p of players.values()) {
        p.muted = true;
        const primed = p.play();
        if (primed && primed.then) {
          primed.then(() => { p.pause(); p.currentTime = 0; p.muted = false; })
            .catch(() => { p.muted = false; });
        } else {
          p.pause(); p.currentTime = 0; p.muted = false;
        }
      }
    } catch (e) { /* non-fatal */ }
    this.unlocked = true;
  },

  // speak(text, {onWord(index), onEnd()}) — drives karaoke + gating.
  speak(text, { onWord, onEnd } = {}) {
    this.stop(false);
    const words = text.split(/\s+/).filter(Boolean);
    const timers = [];
    const entry = CFG.useVoice ? MANIFEST[text] : null;
    if (CFG.useVoice && !entry) {
      console.warn('[audio] no baked clip for text (rerun tools/bake-audio.py?):', text.slice(0, 50));
    }
    const run = { timers, player: entry ? players.get(entry.src) : null };
    currentRun = run;

    let wordTimes, endAt;
    if (entry) {
      wordTimes = entry.words;
      endAt = entry.dur + CFG.endPadMs;
      resetPlayer(run.player);
      const p = run.player.play();
      if (p && p.catch) p.catch(err => console.warn('[audio] play failed:', err && err.name));
    } else {
      wordTimes = words.map((w, i) => i * CFG.wordMs);
      endAt = words.length * CFG.wordMs + CFG.tailMs;
    }

    words.forEach((w, i) => {
      timers.push(setTimeout(() => { if (onWord) onWord(i); }, wordTimes[i] != null ? wordTimes[i] : i * CFG.wordMs));
    });
    timers.push(setTimeout(() => {
      if (run.player) resetPlayer(run.player);
      currentRun = null;
      if (onEnd) onEnd();
    }, endAt));
    return { durationMs: endAt };
  },

  // Real clip length (with end pad) or the synthetic estimate — keeps the
  // audio-pill progress bars honest against the baked files.
  durationMs(text) {
    const entry = CFG.useVoice ? MANIFEST[text] : null;
    if (entry) return entry.dur + CFG.endPadMs;
    return text.split(/\s+/).filter(Boolean).length * CFG.wordMs + CFG.tailMs;
  },

  // stop(fade) — fade=true on early advance (Justin: fade out, never hard-cut).
  stop(fade = true) { cancelRun(fade); },
};
